## Why This Is Asked
This problem evaluates the ability to design a practical dynamic sequence with non-trivial frequency queries—a common requirement in analytics and data processing systems.

## Key Concepts
- **Sqrt decomposition** for dynamic sequences partitions data into blocks of approximately √n elements
- **Per-block frequency maps** enable O(√n) rangeFreq queries
- **Block maintenance**: splits when blocks overflow and merges when they underflow to maintain balance
- **Edge handling**: properly handles partial blocks during queries and updates

## Code Example
```javascript
class Block {
  constructor() {
    this.values = [];
    this.freq = new Map();
  }

  rebuild() {
    this.freq.clear();
    for (const v of this.values) {
      this.freq.set(v, (this.freq.get(v) || 0) + 1);
    }
  }
}

class DynamicSequence {
  constructor() {
    this.blocks = [];
    this.B = Math.ceil(Math.sqrt(10));
  }

  locate(index) {
    let offset = 0;
    for (const block of this.blocks) {
      if (offset + block.values.length > index) {
        return { block, pos: index - offset };
      }
      offset += block.values.length;
    }
  }

  append(value) {
    if (this.blocks.length === 0) this.blocks.push(new Block());
    const last = this.blocks[this.blocks.length - 1];
    last.values.push(value);
    last.freq.set(value, (last.freq.get(value) || 0) + 1);
    if (last.values.length > 2 * this.B) this.split(last);
  }

  split(block) {
    const mid = Math.floor(block.values.length / 2);
    const newBlock = new Block();
    newBlock.values = block.values.splice(mid);
    block.rebuild();
    newBlock.rebuild();
    this.blocks.push(newBlock);
  }

  rangeFreq(l, r, value) {
    let count = 0;
    const { block: startBlock, pos: startPos } = this.locate(l);
    const { block: endBlock, pos: endPos } = this.locate(r);

    if (startBlock === endBlock) {
      for (let i = startPos; i <= endPos; i++) {
        if (startBlock.values[i] === value) count++;
      }
      return count;
    }

    for (let i = startPos; i < startBlock.values.length; i++) {
      if (startBlock.values[i] === value) count++;
    }
    for (const block of this.blocks) {
      if (block === startBlock || block === endBlock) continue;
      count += block.freq.get(value) || 0;
    }
    for (let i = 0; i <= endPos; i++) {
      if (endBlock.values[i] === value) count++;
    }
    return count;
  }
}
```

## Why This Is Asked
Tests ability to design a dynamic string structure supporting weighted, prefix-based queries and order-statistics. A Trie augmented with per-node aggregates enables efficient prefix sums and k-th retrieval while handling duplicates via cumulative weights.

## Key Concepts
- Trie with per-node aggregates (subtreeWeight, terminalWeight)
- O(len(word)) time complexity for insert/erase operations
- O(len(prefix)) for prefix-sum queries
- O(len(prefix) + len(target_word)) for kth-word queries
- Duplicate handling via cumulative weight values

## Code Example
```javascript
class WeightedTrie {
  constructor() {
    this.root = new TrieNode();
  }

  insertWord(word, w) {
    let node = this.root;
    for (const char of word) {
      const idx = char.charCodeAt(0) - 97;
      if (!node.children[idx]) node.children[idx] = new TrieNode();
      node = node.children[idx];
      node.subtreeWeight += w;
    }
    node.terminalWeight += w;
  }

  eraseWord(word, w) {
    this.insertWord(word, -w);
  }

  queryPrefixSum(prefix) {
    let node = this.traverse(prefix);
    return node ? node.subtreeWeight : 0;
  }

  kthWordWithPrefix(prefix, k) {
    let node = this.traverse(prefix);
    if (!node || node.subtreeWeight < k) return null;
    let word = prefix;
    while (!node.terminalWeight) {
      for (let i = 0; i < 26; i++) {
        if (!node.children[i]) continue;
        if (node.children[i].subtreeWeight >= k) {
          word += String.fromCharCode(97 + i);
          node = node.children[i];
          break;
        }
        k -= node.children[i].subtreeWeight;
      }
    }
    return word;
  }

  traverse(prefix) {
    let node = this.root;
    for (const char of prefix) {
      const idx = char.charCodeAt(0) - 97;
      if (!node.children[idx]) return null;
      node = node.children[idx];
    }
    return node;
  }
}

class TrieNode {
  constructor() {
    this.children = new Array(26).fill(null);
    this.subtreeWeight = 0;
    this.terminalWeight = 0;
  }
}
```

