## Why This Is Asked
This question tests understanding of order statistics in dynamic multisets with duplicates and efficient prefix queries—skills fundamental to database indexing and ranking problems.

## Key Concepts
- **Balanced BST with per-node counts and subtree sizes** enables O(log n) operations
- **Handling duplicates via dupCount** avoids unnecessary node creation
- **getRank as a prefix-count query** is analogous to order statistics

## Code Example
```javascript
class Node {
  constructor(key) {
    this.key = key;
    this.dup = 1;
    this.left = null;
    this.right = null;
  }

  get size() {
    return this.dup + (this.left?.size ?? 0) + (this.right?.size ?? 0);
  }
}

class Treap {
  constructor() {
    this.root = null;
  }

  insert(key) {
    this.root = this._insert(this.root, key);
  }

  _insert(node, key) {
    if (!node) return new Node(key);
    if (key === node.key) {
      node.dup++;
    } else if (key < node.key) {
      node.left = this._insert(node.left, key);
    } else {
      node.right = this._insert(node.right, key);
    }
    return node;
  }

  erase(key) {
    this.root = this._erase(this.root, key);
  }

  _erase(node, key) {
    if (!node) return null;
    if (key === node.key) {
      node.dup--;
      if (node.dup === 0) return this._merge(node.left, node.right);
    } else if (key < node.key) {
      node.left = this._erase(node.left, key);
    } else {
      node.right = this._erase(node.right, key);
    }
    return node;
  }

  _merge(left, right) {
    if (!left || !right) return left ?? right;
    // Simplified: in a real Treap, merge by priority
    return this._bstMerge(left, right);
  }

  _bstMerge(left, right) {
    if (!left) return right;
    if (!right) return left;
    const node = left;
    node.right = this._bstMerge(node.right, right);
    return node;
  }

  getRank(v) {
    return this._getRank(this.root, v);
  }

  _getRank(node, v) {
    if (!node) return 0;
    if (v < node.key) {
      return this._getRank(node.left, v);
    }
    const leftSize = node.left?.size ?? 0;
    return leftSize + node.dup + this._getRank(node.right, v);
  }
}
```

## Why This Is Asked
This question tests knowledge of 1D interval stabbing with dynamic updates and top-k queries across overlapping intervals—a common pattern in calendars, ad slot management, and reservation systems.

## Key Concepts
- **Segment tree**: Enables O(log N) node updates for interval operations and point queries
- **Per-node weight multisets**: Maintain counts of overlapping weights using BST/treap for O(log N) rank queries
- **Path aggregation**: Combines structures along the root-to-leaf path to answer sum and kth-largest queries

## Data Layout
1. **Coordinate compression**: Map all interval endpoints to sorted indices (0 to N-1)
2. **Segment tree nodes**: Each node stores a BST of (weight, count) pairs and nodeSum (total weight in that segment)
3. **Query paths**: Both sumWeightsAt and kthLargestWeightAt traverse O(log N) nodes along the path to point x

## Code Example
```javascript
class IntervalSet {
  constructor(points) {
    this.coords = this.compress(points);
    this.tree = this.build(0, this.coords.length - 1);
  }

  compress(points) {
    return [...new Set(points)].sort((a, b) => a - b);
  }

  insertInterval(L, R, w) {
    const l = this.lowerBound(L), r = this.lowerBound(R);
    this.update(this.tree.root, l, r, w, 1);
  }

  eraseInterval(L, R, w) {
    const l = this.lowerBound(L), r = this.lowerBound(R);
    this.update(this.tree.root, l, r, w, -1);
  }

  update(node, L, R, w, delta) {
    if (!node || L > node.r || R < node.l) return;
    if (L <= node.l && node.r <= R) {
      node.bst.insert(w, delta);
      node.sum += w * delta;
      return;
    }
    this.update(node.left, L, R, w, delta);
    this.update(node.right, L, R, w, delta);
  }

  sumWeightsAt(x) {
    const idx = this.lowerBound(x);
    return this.querySum(this.tree.root, idx);
  }

  querySum(node, idx) {
    if (!node) return 0;
    let res = node.sum;
    const mid = Math.floor((node.l + node.r) / 2);
    if (idx <= mid) res += this.querySum(node.left, idx);
    else res += this.querySum(node.right, idx);
    return res;
  }

  kthLargestWeightAt(x, k) {
    const idx = this.lowerBound(x);
    return this.queryKth(this.tree.root, idx, k);
  }

  queryKth(node, idx, k) {
    if (!node) return null;
    const counts = this.getPathCounts(node, idx);
    let lo = 0, hi = this.maxWeight;
    while (lo < hi) {
      const mid = Math.ceil((lo + hi) / 2);
      if (this.countGTE(counts, mid) >= k) lo = mid;
      else hi = mid - 1;
    }
    return lo;
  }
}
```

## Complexity Analysis
- **insertInterval/eraseInterval**: O(log N) nodes × O(log M) BST ops = O(log² N)
- **sumWeightsAt**: O(log N) path traversal
- **kthLargestWeightAt**: O(log N) × O(log maxWeight) = O(log² N)

## Why This Is Asked
Autocomplete systems in product search need fast prefix queries with duplicates. A Trie with per-node counts shows practical memory/time trade-offs and handles duplicates transparently.

## Key Concepts
- Trie with endCount and subCount
- Duplicate handling via counts
- O(|word|) insertion/erasure/lookup
- O(|prefix|) prefix query
- Space proportional to total characters stored

## Code Example
```javascript
class Node { constructor(){ this.next = new Map(); this.end=0; this.sub=0; } }
class Trie { constructor(){ this.root=new Node(); }
  insertWord(w){ let cur=this.root; cur.sub++; for(const ch of w){ if(!cur.next.has(ch)) cur.next.set(ch,new Node()); cur=cur.next.get(ch); cur.sub++; } cur.end++; }
  eraseWord(w){ let cur=this.root; cur.sub--; for(const ch of w){ cur=cur.next.get(ch); cur.sub--; } cur.end--; }
  containsWord(w){ let cur=this.root; for(const ch of w){ if(!cur.next.has(ch)) return false; cur=cur.next.get(ch); } return cur.end>0; }
  countWithPrefix(pref){ let cur=this.root; for(const ch of pref){ if(!cur.next.has(ch)) return 0; cur=cur.next.get(ch); } return cur.sub; }
}
```

